"""Demo copy for the e-commerce niches. Prices are in rupees here; the builder converts them to paise.
Each product's `draw` is (object, main colour, accent colour[, label]) for images/ecommerce_images.py."""


def P(name, cat, price, stock, short, draw, compare=0, featured=False, badge='', variants=None, option=''):
    slug = ''.join(ch if ch.isalnum() else '-' for ch in name.lower()).strip('-')
    while '--' in slug:
        slug = slug.replace('--', '-')
    return {'name': name, 'slug': slug, 'cat': cat, 'price': price, 'compare': compare, 'stock': stock, 'featured': featured, 'badge': badge,
            'short': short, 'draw': draw, 'variants': variants or [], 'option': option}


def C(name, slug, desc, details, hsn, gst):
    return {'name': name, 'slug': slug, 'description': desc, 'details': details, 'hsn': hsn, 'gst': gst}


def f(icon, title, desc):
    return {'icon': icon, 'title': title, 'description': desc}


